/* Médecine du travail : charge exclusivement employeur, tarif documenté. */
const beforeHealthRich=richVar;
richVar=function(p){const c=db.companies.find(c=>c.id===company),v=beforeHealthRich(p);return{healthMode:'À renseigner',healthAmount:'',healthRate:'',healthProvider:c.occupationalHealth||'',healthReference:'',...v};};
const beforeHealthMarkup=variableMarkup;
variableMarkup=function(p){const v=richVar(p);return beforeHealthMarkup(p)+section('Médecine du travail · santé au travail',field('healthProvider','Service de santé au travail (ex. APST BTP / PREVLINK)',v.healthProvider)+selectField('healthMode','Mode de calcul — exclusivement employeur',v.healthMode,['À renseigner','Forfait de la période','Taux documenté sur le brut','Non imputé ce mois'])+field('healthAmount','Forfait affecté à cette période (€)',v.healthAmount,'number','min="0" step=".01"')+field('healthRate','Taux contractuel documenté (%)',v.healthRate,'number','min="0" max="100" step=".0001"')+field('healthReference','Facture / tarif et période couverte',v.healthReference)+`<p class="wide notice" id="healthLive" aria-live="polite"></p><p class="wide muted">Aucune part salariale : le montant ne réduit pas le net à payer. Pour un SPSTI, l’offre socle est financée par une cotisation par travailleur, selon la grille du service. Aucun taux national ni forfait par défaut n’est appliqué. Renseignez le montant ou le taux figurant sur votre document, la période couverte et le service. Ne répétez pas une cotisation annuelle sur chaque mois. Ce suivi de coût employeur ne déclenche aucun paiement ni déclaration.</p>`);};
const beforeHealthEngine=engineInput;
engineInput=function(v){return{...beforeHealthEngine(v),healthMode:v.healthMode,healthAmount:v.healthAmount,healthRate:v.healthRate,healthReference:v.healthReference,healthProvider:v.healthProvider};};
const beforeHealthRead=readVariableForm;
readVariableForm=function(f){const v=beforeHealthRead(f);if(['Forfait de la période','Taux documenté sur le brut'].includes(v.healthMode)){if(!v.healthReference.trim())throw Error('Renseignez la facture / le tarif de santé au travail et la période couverte.');if(v.healthMode==='Forfait de la période'&&v.healthAmount==='')throw Error('Renseignez le forfait santé au travail.');if(v.healthMode==='Taux documenté sur le brut'&&v.healthRate==='')throw Error('Renseignez le taux de santé au travail documenté.');}return v;};
const beforeHealthRefresh=refreshCalculations;
refreshCalculations=function(){beforeHealthRefresh();const out=$('#healthLive');if(!out)return;try{const v=autoVariables(Object.fromEntries(new FormData($('#form'))));const r=PayrollTest.calculate({...engineInput(v),rows:[],taxableNet:'0',socialNet:'',pasRate:'0',advance:'0',otherDeduction:'0'});out.textContent=['Forfait de la période','Taux documenté sur le brut'].includes(v.healthMode)?`Santé au travail : ${euroFmt(r.healthCost)} employeur · 0,00 € salarié. Aucun impact sur le net.`:'Montant à renseigner ou non imputé sur cette période.';}catch(e){out.textContent=e.message;}};
const beforeHealthCompany=companyEdit;
companyEdit=function(){beforeHealthCompany();const c=db.companies.find(c=>c.id===company);$('#formError').insertAdjacentHTML('beforebegin',section('Service de prévention et de santé au travail',field('occupationalHealth','Service de santé au travail / médecine du travail',c.occupationalHealth||'')+field('occupationalHealthReference','Numéro d’adhérent / référence de service',c.occupationalHealthReference||'')));};
const beforeHealthRender=render;
render=function(){beforeHealthRender();if(view==='Entreprise'){const c=db.companies.find(c=>c.id===company);$('#app').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:20px"><h2>Médecine du travail</h2><p>${esc(c.occupationalHealth||'Service à renseigner')}${c.occupationalHealthReference?' · '+esc(c.occupationalHealthReference):''}</p><p class="muted">Tarif et période d’imputation à renseigner dans les cotisations de chaque préparation.</p></section>`);}};
render();
